#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main() {
    FILE *f1 = fopen("/app/image.ppm", "rb");
    FILE *f2 = fopen("reconstructed.ppm", "rb");

    char magic1[10], magic2[10];
    int w1, h1, m1, w2, h2, m2;

    fscanf(f1, "%s %d %d %d", magic1, &w1, &h1, &m1);
    fscanf(f2, "%s %d %d %d", magic2, &w2, &h2, &m2);

    if(w1 != w2 || h1 != h2) {
        printf("Size mismatch: %dx%d vs %dx%d\n", w1, h1, w2, h2);
        return 1;
    }

    unsigned char *pix1 = malloc(w1 * h1 * 3);
    unsigned char *pix2 = malloc(w2 * h2 * 3);

    fread(pix1, 1, w1 * h1 * 3, f1);
    fread(pix2, 1, w2 * h2 * 3, f2);

    fclose(f1);
    fclose(f2);

    // Compute L2 similarity
    double sum_sq_diff = 0, sum_sq1 = 0, sum_sq2 = 0;
    for(int i = 0; i < w1 * h1 * 3; i++) {
        double v1 = pix1[i];
        double v2 = pix2[i];
        double d = v1 - v2;
        sum_sq_diff += d * d;
        sum_sq1 += v1 * v1;
        sum_sq2 += v2 * v2;
    }

    // Normalized L2 similarity
    double norm1 = sqrt(sum_sq1);
    double norm2 = sqrt(sum_sq2);
    double similarity = 1.0 - (sqrt(sum_sq_diff) / (norm1 + norm2 + 1e-10));

    printf("L2 Similarity: %.6f\n", similarity);
    printf("Sum squared diff: %e\n", sum_sq_diff);
    printf("Norm1: %e, Norm2: %e\n", norm1, norm2);

    // Sample first differences
    printf("\nFirst 20 pixel differences:\n");
    for(int i = 0; i < 20; i++) {
        printf("(%d,%d,%d) vs (%d,%d,%d) diff=(%d,%d,%d)\n", 
            pix1[i*3], pix1[i*3+1], pix1[i*3+2],
            pix2[i*3], pix2[i*3+1], pix2[i*3+2],
            pix1[i*3]-pix2[i*3], pix1[i*3+1]-pix2[i*3+1], pix1[i*3+2]-pix2[i*3+2]);
    }

    return 0;
}
