      }else{
        // Ray traced scene: sphere at center with checkerboard floor
        float dx=(u-0.5)*2.0, dy=(v-0.5)*2.0;
        float d2=dx*dx+dy*dy;

        if(d2<0.2){
          // Red sphere
          r=51; g=10; b=10;
        }else if(d2<0.25){
          // Soft shadow/penumbra
          float t=(sqrt(d2)-sqrt(0.2))/(sqrt(0.25)-sqrt(0.2));
          r=(int)(51+(152-51)*t);
          g=(int)(10+(67-10)*t);
          b=(int)(10+(67-10)*t);
