          // Checkerboard floor
          int cx=(int)(u*8), cy=(int)((v-0.5)*6);
          if((cx+cy)%2==0){r=g=b=152;}
          else{r=g=b=67;}
        }
      }

      r=(r<0)?0:((r>255)?255:r);
      g=(g<0)?0:((g>255)?255:g);
